mapper.select:
select snapshot_id, deploy_id, process_key, element_id, extension_key,
       extension_version_id, version_no, extension_type, implementation_key,
       config_json, version_checksum, snapshot_checksum, create_by, create_time
from wf_deploy_extension_snapshot
where deploy_id = #{deployId}
  and process_key = #{processKey}
  and element_id = #{elementId}
